CREATE TABLE IF NOT EXISTS schema_version(version INTEGER PRIMARY KEY CHECK(version=1));
INSERT OR IGNORE INTO schema_version VALUES(1);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, username TEXT UNIQUE NOT NULL, display_name TEXT NOT NULL, password_hash TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), csrf TEXT NOT NULL, expires REAL NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts(bucket TEXT PRIMARY KEY, attempts INTEGER NOT NULL, window_start REAL NOT NULL);
CREATE TABLE IF NOT EXISTS labs(id TEXT PRIMARY KEY, name TEXT NOT NULL, owner_id TEXT NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS lab_members(lab_id TEXT REFERENCES labs(id), user_id TEXT REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('owner','admin','member')), PRIMARY KEY(lab_id,user_id));
CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY, lab_id TEXT NOT NULL REFERENCES labs(id), name TEXT NOT NULL, description TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS project_members(project_id TEXT REFERENCES projects(id), user_id TEXT REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('admin','editor','viewer')), PRIMARY KEY(project_id,user_id));
CREATE TABLE IF NOT EXISTS records(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), version INTEGER NOT NULL, payload TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS revisions(record_id TEXT REFERENCES records(id), version INTEGER NOT NULL, payload TEXT NOT NULL, archived INTEGER NOT NULL, actor_id TEXT REFERENCES users(id), at TEXT NOT NULL, PRIMARY KEY(record_id,version));
CREATE TABLE IF NOT EXISTS comments(id TEXT PRIMARY KEY, record_id TEXT NOT NULL REFERENCES records(id), body TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES users(id), at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS links(id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES records(id), target_id TEXT NOT NULL REFERENCES records(id), relation TEXT NOT NULL CHECK(relation IN ('repeat_of','fix_for','derived_from')), actor_id TEXT REFERENCES users(id), at TEXT NOT NULL, UNIQUE(source_id,target_id,relation));
CREATE TABLE IF NOT EXISTS attachments(id TEXT PRIMARY KEY, record_id TEXT NOT NULL REFERENCES records(id), filename TEXT NOT NULL, sha256 TEXT NOT NULL, size INTEGER NOT NULL, content BLOB NOT NULL, actor_id TEXT REFERENCES users(id), at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY AUTOINCREMENT, lab_id TEXT REFERENCES labs(id), project_id TEXT REFERENCES projects(id), actor_id TEXT REFERENCES users(id), action TEXT NOT NULL, subject_id TEXT NOT NULL, detail TEXT NOT NULL, at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS imports(project_id TEXT REFERENCES projects(id), connector TEXT NOT NULL, external_id TEXT NOT NULL, payload_sha256 TEXT NOT NULL, record_id TEXT REFERENCES records(id), PRIMARY KEY(project_id,connector,external_id));
CREATE INDEX IF NOT EXISTS records_project ON records(project_id,archived);
CREATE INDEX IF NOT EXISTS events_project ON events(project_id,id);
CREATE INDEX IF NOT EXISTS links_target ON links(target_id);
